header-navigation.css:
/* Shared public header: one tree, desktop information rows and the existing native drawer. */
/* Shared public header: one tree, single-row desktop and the existing native drawer. */

/* Parish information shares the real navigation tree with the native mobile drawer. */
.header-information,.header-opening { display:none; }
.drawer-information-title { display:none; }
@media(min-width:1536px) {
 .site-header:not(.is-condensed) .nav-wrap { grid-template-rows:44px 48px; column-gap:20px; padding-block:8px; }
 .site-header:not(.is-condensed) .header-branding { grid-row:1/3; align-self:stretch; padding-right:20px; border-right:1px solid var(--navigation-line); }
 .site-header:not(.is-condensed) .nav-primary,.site-header:not(.is-condensed) .nav-utilities { grid-row:2; }
 .site-header:not(.is-condensed) .header-information { display:flex; align-items:center; grid-column:2; grid-row:1; align-self:stretch; gap:18px; border-bottom:1px solid var(--navigation-line); }
 .site-header:not(.is-condensed) .header-opening { display:flex; justify-content:flex-end; align-items:center; grid-column:3; grid-row:1; align-self:stretch; border-bottom:1px solid var(--navigation-line); }
 .header-information a,.site-header .header-opening { color:var(--navigation-ink); font:500 16px/1.4 var(--serif); min-height:44px; gap:9px; }
 .header-information a { display:inline-flex; align-items:center; }
 .header-information a + a { position:relative; padding-left:18px; }
 .header-information a + a::before { content:''; position:absolute; left:0; height:20px; border-left:1px solid var(--navigation-gold); }
 .header-information svg,.header-opening svg { color:var(--navigation-gold); width:23px; height:23px; flex:none; }
 .header-information a:hover,.site-header .header-opening:hover { text-decoration:underline; text-underline-offset:4px; }
 .site-header:not(.is-condensed) .navigation-hub { max-height:calc(100dvh - 140px); }
 /* Extra height is absorbed by the header's existing fixed reserve, not the page flow. */
 :root { --header-reserve:108px; }
}
.responsive-navigation-dialog .header-information { display:grid; grid-template-columns:1fr; gap:0; padding:8px 0 16px; margin-bottom:8px; border-bottom:1px solid var(--navigation-line); }
.responsive-navigation-dialog .drawer-information-title { display:block; margin:0 0 8px; color:#6e551b; font:600 12px/1.5 var(--sans); letter-spacing:.1em; text-transform:uppercase; }
.responsive-navigation-dialog .header-information a { display:flex; align-items:center; gap:12px; min-height:48px; color:var(--navigation-ink); font:600 20px/1.4 var(--serif); }
.responsive-navigation-dialog .header-information svg { width:24px; height:24px; color:var(--navigation-gold); flex:none; }
.responsive-navigation-dialog .header-opening { display:none; }
.safeguarding-guidance-links { margin-top:22px!important; }

